/* ============================================================
   样稿共享脚本：主题切换 / 图标注入 / 考试切换器 / 页头滚动边线
   全部为演示交互，无真实接口。
   ============================================================ */
(function () {
  'use strict';

  /* ---------- 图标注入：<i class="ic" data-icon="search"></i> ---------- */
  function injectIcons(root) {
    (root || document).querySelectorAll('[data-icon]').forEach(function (el) {
      var svg = ICONS[el.getAttribute('data-icon')];
      if (svg) el.innerHTML = svg;
    });
  }
  window.protoIcon = function (name) { return ICONS[name] || ''; };
  window.injectIcons = injectIcons;

  /* ---------- 主题切换 ---------- */
  function initTheme() {
    var current = document.documentElement.getAttribute('data-theme') || 'a';
    document.querySelectorAll('.theme-toggle button').forEach(function (btn) {
      btn.classList.toggle('on', btn.getAttribute('data-set') === current);
      btn.addEventListener('click', function () {
        var t = btn.getAttribute('data-set');
        document.documentElement.setAttribute('data-theme', t);
        try { localStorage.setItem('proto-theme', t); } catch { /* 静态原型可忽略 */ }
        document.querySelectorAll('.theme-toggle button').forEach(function (b) {
          b.classList.toggle('on', b === btn);
        });
      });
    });
  }

  /* ---------- 页头滚动边线 ---------- */
  function initHeaderScroll() {
    var main = document.querySelector('.main');
    var header = document.querySelector('.page-header');
    if (!main || !header) return;
    var update = function () { header.classList.toggle('is-scrolled', main.scrollTop > 4); };
    main.addEventListener('scroll', update, { passive: true });
    update();
  }

  /* ---------- Ctrl+K → 聚焦快速跳转 ---------- */
  function initQuickJump() {
    var pill = document.querySelector('.sb-search');
    if (!pill) return;
    document.addEventListener('keydown', function (e) {
      if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === 'k') {
        e.preventDefault();
        pill.focus();
      }
    });
  }

  /* ---------- 考试切换器 ---------- */
  var EXAMS = [
    { name: '第五周单元测验《实数》', date: '9 月 26 日', sem: '上', st: 'rev', stText: '待复核', progress: 100, count: 90, review: 12 },
    { name: '第三章勾股定理测验', date: '9 月 19 日', sem: '上', st: 'done', stText: '批改完成', progress: 100, count: 88, review: 0 },
    { name: '九月月考', date: '9 月 12 日', sem: '上', st: 'done', stText: '批改完成', progress: 100, count: 87, review: 0 },
    { name: '第二章实数强化练习', date: '9 月 5 日', sem: '上', st: 'run', stText: '批改中', progress: 62, count: 89, review: 0 },
    { name: '八下预习摸底测验', date: '9 月 2 日', sem: '下', st: 'done', stText: '批改完成', progress: 100, count: 90, review: 0 },
  ];
  var stCls = { rev: 'chip--rev', done: 'chip--done', run: 'chip--run' };

  function examItemHtml(ex, idx, current) {
    return '<button class="exam-item" data-idx="' + idx + '" role="option" aria-selected="' + current + '">'
      + '<span class="exam-item__name">' + (current ? '<i class="ic">' + protoIcon('check') + '</i>' : '<span style="width:14px;display:inline-block;flex:none"></span>') + ex.name + '</span>'
      + '<span class="exam-item__right">'
      + (ex.review > 0 ? '<span class="exam-item__count">待复核 ' + ex.review + '</span>' : '')
      + '<span class="chip ' + stCls[ex.st] + '">' + ex.stText + '</span></span>'
      + '<span class="exam-item__row"><span>' + ex.date + '</span><span>·</span><span>' + ex.count + ' 份</span>'
      + '<span class="exam-item__bar ' + (ex.progress >= 100 ? 'is-done' : '') + '"><i style="width:' + ex.progress + '%"></i></span>'
      + '</span></button>';
  }

  function initExamSwitcher() {
    var wrap = document.querySelector('.sb-exam');
    var card = document.getElementById('examCard');
    var pop = document.getElementById('examPop');
    if (!wrap || !card || !pop) return;
    var currentIdx = 0;
    var semFilter = '全部';
    var query = '';

    function renderList() {
      var list = pop.querySelector('.exam-pop__list');
      list.innerHTML = EXAMS.map(function (ex, i) {
        var okSem = semFilter === '全部' || ex.sem === (semFilter === '八年级上' ? '上' : '下');
        var okQ = !query || ex.name.indexOf(query) !== -1;
        return (okSem && okQ) ? examItemHtml(ex, i, i === currentIdx) : '';
      }).join('') || '<div style="padding:14px 10px;font-size:12.5px;color:var(--ink-3)">没有匹配的考试</div>';
      injectIcons(list);
      list.querySelectorAll('.exam-item').forEach(function (btn) {
        btn.addEventListener('click', function () {
          selectExam(Number(btn.getAttribute('data-idx')));
          close();
        });
      });
    }
    function selectExam(i) {
      currentIdx = i;
      var ex = EXAMS[i];
      card.classList.remove('exam-card--empty');
      card.querySelector('.exam-card__name').textContent = ex.name;
      var chipEl = card.querySelector('.exam-card__meta .chip');
      chipEl.className = 'chip ' + stCls[ex.st];
      chipEl.textContent = ex.stText + (ex.st === 'rev' ? ' ' + ex.review : '');
      card.querySelector('.exam-card__bar i').style.width = ex.progress + '%';
      card.querySelector('.exam-card__bar i').style.background = ex.progress >= 100 ? 'var(--st-done)' : 'var(--st-run)';
      card.querySelector('.exam-card__sub').textContent = '八年级' + ex.sem + ' · ' + ex.count + ' 份答卷';
      renderList();
    }
    function open() {
      pop.hidden = false;
      card.setAttribute('aria-expanded', 'true');
      renderList();
      var input = pop.querySelector('input');
      if (input) setTimeout(function () { input.focus(); }, 30);
    }
    function close() {
      pop.hidden = true;
      card.setAttribute('aria-expanded', 'false');
    }
    card.addEventListener('click', function (e) {
      e.stopPropagation();
      if (pop.hidden) { open(); } else { close(); }
    });
    pop.addEventListener('click', function (e) { e.stopPropagation(); });
    document.addEventListener('click', close);
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') close(); });
    var search = pop.querySelector('input');
    if (search) search.addEventListener('input', function () { query = search.value.trim(); renderList(); });
    pop.querySelectorAll('.fchip').forEach(function (chip) {
      chip.addEventListener('click', function () {
        semFilter = chip.textContent.trim();
        pop.querySelectorAll('.fchip').forEach(function (c) { c.classList.toggle('on', c === chip); });
        renderList();
      });
    });
  }

  /* ---------- 数字滚动 ---------- */
  window.protoCountUp = function (el, target, opts) {
    opts = opts || {};
    var dur = opts.dur || 400;
    var dec = opts.dec || 0;
    var suffix = opts.suffix || '';
    var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduced) { el.textContent = target.toFixed(dec) + suffix; return; }
    var t0 = null;
    function step(ts) {
      if (!t0) t0 = ts;
      var p = Math.min(1, (ts - t0) / dur);
      var e = 1 - Math.pow(1 - p, 3);
      el.textContent = (target * e).toFixed(dec) + suffix;
      if (p < 1) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  };

  /* ---------- 答卷扫描占位 SVG ---------- */
  window.scanSVG = function (opts) {
    opts = opts || {};
    var w = opts.w || 200, h = opts.h || 120;
    var letter = opts.letter || 'B';
    var lines = '';
    var y;
    for (y = 14; y < h - 10; y += 13) lines += '<line class="pline" x1="8" y1="' + y + '" x2="' + (w - 8) + '" y2="' + y + '"/>';
    var rx = opts.rx != null ? opts.rx : Math.round(w * 0.14);
    var rw = opts.rw != null ? opts.rw : Math.round(w * 0.66);
    var rh = opts.rh != null ? opts.rh : Math.round(h * 0.4);
    var ry = opts.ry != null ? opts.ry : Math.round((h - rh) / 2);
    var lx = rx + rw * 0.46;
    var ly = ry + rh * 0.68;
    var marks = opts.mark || '';
    return '<svg class="scan" viewBox="0 0 ' + w + ' ' + h + '" preserveAspectRatio="xMidYMid slice">'
      + '<rect class="paper" width="' + w + '" height="' + h + '"/>' + lines
      + '<text class="ptext" x="10" y="22" font-size="9">' + (opts.caption || '2．下列说法正确的是（　　）') + '</text>'
      + '<text class="ptext" x="10" y="' + (h - 10) + '" font-size="7">' + (opts.foot || '解：') + '</text>'
      + '<rect class="region" x="' + rx + '" y="' + ry + '" width="' + rw + '" height="' + rh + '" rx="2"/>'
      + '<text class="hand" x="' + lx + '" y="' + ly + '" font-size="' + Math.round(rh * 0.62) + '">' + letter + '</text>'
      + marks
      + '</svg>';
  };

  /* ---------- 简单下拉菜单（更多 ▾） ---------- */
  window.initDropdown = function (btnId, menuId) {
    var btn = document.getElementById(btnId);
    var menu = document.getElementById(menuId);
    if (!btn || !menu) return;
    btn.addEventListener('click', function (e) {
      e.stopPropagation();
      var open = !menu.hidden;
      menu.hidden = open;
      btn.setAttribute('aria-expanded', String(!open));
    });
    menu.addEventListener('click', function (e) { e.stopPropagation(); });
    document.addEventListener('click', function () { menu.hidden = true; });
    document.addEventListener('keydown', function (e) { if (e.key === 'Escape') menu.hidden = true; });
  };

  window.showToast = function (text) {
    var t = document.createElement('div');
    t.className = 'toast';
    t.innerHTML = protoIcon('circle-check-big') + '<span>' + text + '</span>';
    document.body.appendChild(t);
    injectIcons(t);
    setTimeout(function () {
      t.style.opacity = '0';
      t.style.transform = 'translateY(6px)';
      t.style.transition = 'opacity 160ms ease, transform 160ms ease';
      setTimeout(function () { t.remove(); }, 200);
    }, 1800);
  };

  document.addEventListener('DOMContentLoaded', function () {
    injectIcons();
    initTheme();
    initHeaderScroll();
    initQuickJump();
    initExamSwitcher();
  });
})();
